-- ── Import Kamativi fuel_log (433 issuances) from old ERP ────────────────────
-- Phase 2b. Each row inserts one fuel_transactions row with transaction_type
-- = 'issuance' against the ZUFTA10 tank, matched to a vehicle or equipment
-- row by canonicalised registration. The old fuel_update_tank_level trigger
-- is bypassed for this bulk historical load; migration 0045 sets the
-- current tank level to the latest known dipstick reading so imported
-- history doesn't perturb it.
--
-- Idempotent — transaction_number (site-unique) is checked before insert.

BEGIN;

SET session_replication_role = 'replica';

DO $$
DECLARE
  v_site_id uuid;
  v_tank_id uuid;
BEGIN
  SELECT id INTO v_site_id FROM sites WHERE lower(name) = 'kamativi' LIMIT 1;
  IF v_site_id IS NULL THEN RAISE EXCEPTION 'Kamativi site not found.'; END IF;

  SELECT id INTO v_tank_id FROM fuel_tanks
   WHERE site_id = v_site_id AND (code = 'ZUFTA10' OR upper(name) = 'MAIN TANK')
   LIMIT 1;
  IF v_tank_id IS NULL THEN RAISE EXCEPTION 'ZUFTA10 tank not found at Kamativi.'; END IF;

  INSERT INTO fuel_transactions (
    site_id, transaction_number, transaction_date, tank_id,
    transaction_type, vehicle_id, equipment_id, asset_description,
    litres, meter_start, docket_number, notes)
  SELECT v_site_id, r.txn, r.date::date, v_tank_id,
         'issuance',
         v.id AS vehicle_id,
         e.id AS equipment_id,
         r.veh_raw AS asset_description,
         r.litres::numeric,
         NULLIF(r.odometer, '')::numeric,
         NULL,
         format('Imported legacy %s — driver: %s, authorised: %s, purpose: %s',
                r.legacy_id, r.driver, r.authorised, r.purpose)
