      ('0960698a-b19c-4f39-8a61-f8c5c0bc10b5', 'FI-2026-00011', '2026-05-15', '50', 'HIRED TLB – backhoe loader', NULL, 'FL-2026-00018', NULL, 'Wendy T. Mpala', 'site use', NULL),
